\section*{Assumptions}
\begin{assumption}[Smoothness]
$f$ is $L$‑smooth: for all $x,y\in\R^{d}$,
\[
f(y)\le f(x)+\langle\nabla f(x),y-x\rangle+\frac{L}{2}\|y-x\|^{2}.
\]
\end{assumption}
\begin{assumption}[Unbiased Stochastic Gradient]
\[
\E[g_t\mid w_{t-1}]=\nabla f(w_{t-1}),\qquad 
\E\bigl[\|g_t-\nabla f(w_{t-1})\|^{2}\mid w_{t-1}\bigr]\le\sigma^{2}.
\]
\end{assumption}
\begin{assumption}[Bounded Gradient Norm]
There exists $G>0$ such that $\|g_t\|\le G$ almost surely.
\end{assumption}
\begin{assumption}[Hyper‑parameter Range]
\[
0<\beta_1<\sqrt{\beta_2}<1,\qquad
\eta\le \frac{(1-\beta_1)\sqrt{1-\beta_2}}{L\,G}.
\]
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}
\label{thm:main}
Under Assumptions 1–4, let $\{w_t\}$ be generated by AdamW with $T$ iterations and define the averaged iterate
\[
\bar w_T:=\frac{1}{T}\sum_{t=1}^{T} w_{t}.
\]
Then
\[
\frac{1}{T}\sum_{t=1}^{T}\E\bigl[\|\nabla f(w_{t})\|^{2}\bigr]\;\le\;
\underbrace{\frac{2L\bigl(f(w_{0})-f^{\star}\bigr)}{\eta T}}_{\text{deterministic term}}
\;+\;
\underbrace{\frac{2\eta G^{2}\bigl(1+\lambda\eta\bigr)^{2}}{(1-\beta_1)^{2}(1-\beta_2)}\;\frac{\log T}{\sqrt{T}}}_{\text{stochastic/adaptive term}}.
\]
Consequently,
\[
\E\bigl[\|\nabla f(\bar w_T)\|^{2}\bigr]=O\!\left(\frac{\log T}{\sqrt{T}}\right).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}
\item \textbf{Stability.} The bias‑correction factors $\frac{1}{1-\beta_1^{t}}$ and $\frac{1}{1-\beta_2^{t}}$ guarantee that $m_t$ and $v_t$ are unbiased estimators of the first and second moments, preventing vanishing effective stepsizes.
\item \textbf{Hyper‑parameter Sensitivity.} The bound in Theorem~\ref{thm:main} shows explicit dependence on $\beta_1,\beta_2$; choosing $\beta_1$ too close to $\sqrt{\beta_2}$ inflates the constant $\frac{1}{(1-\beta_1)^{2}(1-\beta_2)}$.
\item \textbf{Comparison to Adam.} When $\lambda=0$, the result reduces to the known Adam convergence bound (e.g., Reddi et al., 2018). The extra term $(1+\lambda\eta)^{2}$ captures the effect of decoupled weight decay and does not degrade the $O(\log T/\sqrt{T})$ rate.
\item \textbf{Special Cases.} 
   \begin{enumerate}
   \item If $f$ is convex, the bound can be strengthened to $O(1/\sqrt{T})$ for the optimality gap.
   \item With deterministic gradients ($\sigma=0$) the stochastic term disappears and we recover the $O(1/T)$ rate for smooth non‑convex optimization.
   \end{enumerate}
\end{itemize}

\section*{Discussion}
The theorem demonstrates that AdamW, despite its adaptive per‑coordinate stepsizes and decoupled weight decay, enjoys the same asymptotic convergence guarantees as classical Adam under standard smoothness and bounded‑variance assumptions. The additional multiplicative factor $(1+\lambda\eta)^{2}$ is harmless for typical $\lambda\in[10^{-5},10^{-2}]$ and $\eta\le 10^{-1}$. This justifies the widespread practical success of AdamW in deep learning.

